// iOS 27 SDK requires the UIScene life cycle (apps built without it crash at launch).
// Expo SDK 53's template is window-based, so this plugin:
//  1) adds UIApplicationSceneManifest to Info.plist
//  2) writes SceneDelegate.swift, which attaches AppDelegate's window to the scene
//  3) adds SceneDelegate.swift to the Xcode target
const fs = require("fs");
const path = require("path");
const { withInfoPlist, withDangerousMod, withXcodeProject, IOSConfig } = require("expo/config-plugins");

const SCENE_DELEGATE = `import UIKit
import React
import Expo

// Generated by plugins/withSceneLifecycle.js
class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  var window: UIWindow?

  func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options connectionOptions: UIScene.ConnectionOptions) {
    guard let windowScene = scene as? UIWindowScene else { return }
    // AppDelegate still creates the window and starts React Native (expo-dev-launcher needs a window
    // during didFinishLaunching). Here we just attach that window to the scene and show it.
    let appDelegate = UIApplication.shared.delegate as? AppDelegate
    let window = appDelegate?.window ?? UIWindow(windowScene: windowScene)
    window.windowScene = windowScene
    self.window = window
    window.makeKeyAndVisible()
    for ctx in connectionOptions.urlContexts { open(ctx.url) }
  }

  func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {
    for ctx in URLContexts { open(ctx.url) }
  }

  func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {
    _ = UIApplication.shared.delegate?.application?(UIApplication.shared, continue: userActivity, restorationHandler: { _ in })
  }

  private func open(_ url: URL) {
    _ = UIApplication.shared.delegate?.application?(UIApplication.shared, open: url, options: [:])
  }
}
`;

module.exports = (config) => {
  config = withInfoPlist(config, (cfg) => {
    cfg.modResults.UIApplicationSceneManifest = {
      UIApplicationSupportsMultipleScenes: false,
      UISceneConfigurations: {
        UIWindowSceneSessionRoleApplication: [{
          UISceneConfigurationName: "Default Configuration",
          UISceneDelegateClassName: "$(PRODUCT_MODULE_NAME).SceneDelegate",
        }],
      },
    };
    return cfg;
  });

  config = withDangerousMod(config, ["ios", (cfg) => {
    const dir = path.join(cfg.modRequest.platformProjectRoot, cfg.modRequest.projectName);
    fs.writeFileSync(path.join(dir, "SceneDelegate.swift"), SCENE_DELEGATE);
    return cfg;
  }]);

  config = withXcodeProject(config, (cfg) => {
    const name = cfg.modRequest.projectName;
    const filepath = `${name}/SceneDelegate.swift`;
    if (!cfg.modResults.hasFile(filepath)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({ filepath, groupName: name, project: cfg.modResults });
    }
    return cfg;
  });

  return config;
};
